400	// ---- 取包时刻：等待结束、开始核对绑定授权的同一时刻 ----
401	
402	// fetchWhileStoreBusy 模拟取包请求发出后被同一存储上的其他操作阻塞：
403	// 先占用存储互斥锁，再在阻塞期间把时钟推进到 advanceTo，随后放行取包。
404	// 返回取包最终的交付与错误。
405	func fetchWhileStoreBusy(s *Store, clk *fakeClock, advanceTo time.Time, actor Actor, exchangeID ID) (PackageDelivery, error) {
406		s.mu.Lock()
407		type outcome struct {
408			del PackageDelivery
409			err error
410		}
411		done := make(chan outcome, 1)
412		go func() {
413			del, err := s.FetchPackage(actor, exchangeID)
414			done <- outcome{del, err}
415		}()
416		// 给取包 goroutine 留出进入 FetchPackage 并阻塞在锁上的时间，确保请求
417		// 是在时钟推进之前发出的。
418		time.Sleep(50 * time.Millisecond)
419		clk.t = advanceTo
420		s.mu.Unlock()
421		o := <-done
422		return o.del, o.err
423	}
